function (values, root) {
  var code = Number(values.code);
  var family = Math.floor(code / 100);
  var families = {
    1: "1xx: the server is still working",
    2: "2xx: it worked",
    3: "3xx: look somewhere else",
    4: "4xx: the request is wrong",
    5: "5xx: the server is wrong"
  };
  var named = {
    200: "The request worked and the answer is in the body.",
    301: "The thing moved. Ask again at the new address.",
    400: "The bytes you sent do not parse.",
    401: "No usable login came with the request.",
    403: "You are known, and you are still not allowed.",
    404: "There is nothing at that address.",
    500: "The request was fine and the handler failed.",
    502: "The server behind this one answered badly."
  };
  root.querySelector("[data-code]").textContent = code;
  root.querySelector("[data-family]").textContent = families[family] || "not a real family";
  root.querySelector("[data-meaning]").textContent = named[code] || "Slide to 200, 301, 400, 401, 403, 404, 500 or 502 for a named example.";
}
